```javascript
function checkPrime(arr) {
  // Loop through each number in the input array
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];

    // Check if the number is a prime number
    if (isPrime(num)) {
      console.log(`Found prime number: ${num}`);
      // If a prime number is found, break out of the loop
      break;
    }
  }
}

function isPrime(n) {
  // 1 is not a prime number
  if (n === 1) {
    return false;
  }

  // 2 and 3 are prime numbers
  if (n === 2 || n === 3) {
    return true;
  }

  // Even numbers are not prime numbers
  if (n % 2 === 0) {
    return false;
  }

  // Check if n is divisible by any integer between 3 and the square root of n
  for (let I = 3; I <= Math.sqrt(n); I += 2) {
    if (n % I === 0) {
      return false;
    }
  }

  return true;
}

// Example usage
const inputArr = [4, 7, 11, 13, 17];
checkPrime(inputArr);
```

Die Funktion `checkPrime` nimmt ein Array als Eingabe und prüft jedes Element des Arrays auf seine Primzahlseigenschaft. Wenn eine Primzahl gefunden wird, wird sie auf der Konsole ausgegeben und die Schleife wird abgebrochen.

